llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C36"],
      "claim": "Cilomilast, a methoxyphenyl-containing drug, had a mean absolute oral bioavailability of 96% (range 92–102%) in healthy humans, supporting high F for the query's methoxyphenyl/amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Vernakalant, which shares methoxyphenyl and basic amine features with the query, showed absolute oral bioavailability of 71±21% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Irbesartan, despite a polar tetrazole and higher molecular complexity, had absolute oral bioavailability of about 70% in humans, indicating that polar/ionizable groups do not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "In cirrhotic patients, meptazinol—a basic tertiary amine drug with low healthy-state F—had absolute oral bioavailability of 27.9±5.3%, directly matching the query's cirrhosis condition and supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Urapidil, containing methoxyphenyl and basic piperazine, had absolute oral bioavailability of 78% in healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple high-transfer human absolute-bioavailability analogues (cilomilast, vernakalant, irbesartan, urapidil) show F well above 20%, and the only cirrhosis-specific analogue (meptazinol) reaches 27.9% F in cirrhotic patients, matching the query condition. The query's larger size and polar sulfone groups introduce uncertainty, but the weight of direct experimental evidence supports high oral bioavailability.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "The query's high molecular weight (555.7) and TPSA (108.44) are not fully represented by the high-F analogues.",
    "Only one analogue provides cirrhosis-specific data; cirrhosis effects on absorption/transport for this chemotype are uncertain.",
    "Potential efflux or poor permeability contributions of the sulfone groups are not directly addressed by the evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

